changeSet.sql:
update work_site set active = false
where type = 'KHACH_HANG' and name in ('Việt Á', 'LP Bank', 'SeAbank')
  and exists (select 1 from work_assignment a where a.site_id = work_site.id);
delete from work_site
where type = 'KHACH_HANG' and name in ('Việt Á', 'LP Bank', 'SeAbank')
  and not exists (select 1 from work_assignment a where a.site_id = work_site.id);
